function trackbatch_utrack_batch(manifestPath)
%TRACKBATCH_UTRACK_BATCH Run u-track detection + tracking for every job in a manifest.
%   Generated by trackbatch - do not edit; it is overwritten on each run.
%   Requires MATLAB R2016b+ (jsondecode) and u-track 2.x on the path (or
%   manifest.utrack_path pointing at the u-track "software" folder).

manifest = jsondecode(fileread(manifestPath));
if isfield(manifest, 'utrack_path') && ~isempty(manifest.utrack_path)
    addpath(genpath(manifest.utrack_path));
end
if ~exist('trackCloseGapsKalmanSparse', 'file')
    error('trackbatch:noUtrack', ...
        'u-track is not on the MATLAB path. Set the u-track folder in trackbatch.');
end

params = manifest.params;
jobs = manifest.jobs;
if iscell(jobs), jobs = [jobs{:}]; end

for i = 1:numel(jobs)
    job = jobs(i);
    fprintf('[trackbatch] JOB %d START %s (%d/%d)\n', job.id, job.image, i, numel(jobs));
    status = struct('status', 'failed', 'image', job.image, 'error', '', 'stats', struct());
    try
        status.stats = runJob(job, params);
        status.status = 'ok';
    catch err
        status.error = sprintf('%s: %s', err.identifier, err.message);
        if exist('OCTAVE_VERSION', 'builtin')
            fprintf('%s\n', err.message);
        else
            fprintf('%s\n', getReport(err, 'extended', 'hyperlinks', 'off'));
        end
    end
    writeText(fullfile(job.output_dir, 'trackbatch_status.json'), jsonencode(status));
    if strcmp(status.status, 'ok')
        fprintf('[trackbatch] JOB %d OK detections=%d tracks=%d\n', job.id, ...
            status.stats.n_detections, status.stats.n_tracks);
    else
        fprintf('[trackbatch] JOB %d FAILED %s\n', job.id, status.error);
    end
end
end

% -------------------------------------------------------------------------
function stats = runJob(job, params)
t0 = tic;
outDir = job.output_dir;
if ~exist(outDir, 'dir'), mkdir(outDir); end

imgOpt = params.image;
movie = openMovie(job.image, imgOpt.channel);
f1 = max(1, imgOpt.first_frame);
if isempty(imgOpt.last_frame), f2 = movie.nFrames; else, f2 = min(movie.nFrames, imgOpt.last_frame); end
if f2 < f1, error('trackbatch:frames', 'Empty frame range %d..%d', f1, f2); end
nF = f2 - f1 + 1;
fprintf('Movie %s: %d frame(s), analysing %d..%d, channel %d\n', job.image, movie.nFrames, f1, f2, imgOpt.channel);

% ---- detection ----------------------------------------------------------
det = params.detection;
switch det.method
    case 'subres_gaussian'
        frameDir = fullfile(outDir, 'frames_tmp');
        if ~exist(frameDir, 'dir'), mkdir(frameDir); end
        digits = max(4, numel(num2str(f2)));
        for t = f1:f2
            frame = movie.getFrame(t);
            if isfloat(frame)
                frame = uint16(frame);  % detectSubRes reads .tif files; keep integer data
            end
            imwrite(frame, fullfile(frameDir, sprintf(['frame_%0' num2str(digits) 'd.tif'], t)));
        end
        movieParam.imageDir = [frameDir filesep];
        movieParam.filenameBase = 'frame_';
        movieParam.firstImageNum = f1;
        movieParam.lastImageNum = f2;
        movieParam.digits4Enum = digits;
        detectionParam = det.detectionParam;
        saveRes.dir = outDir;
        saveRes.filename = 'detection.mat';
        movieInfo = detectSubResFeatures2D_StandAlone(movieParam, detectionParam, saveRes, 0);
        movieInfo = movieInfo(f1:f2);
        rmdir(frameDir, 's');
    case 'point_source'
        ps = det.pointSource;
        sigma = ps.sigma;
        opts = {};
        names = setdiff(fieldnames(ps), {'sigma'});
        logicalOpts = {'FitMixtures', 'RemoveRedundant', 'Prefilter', 'RefineMaskLoG', 'RefineMaskValid'};
        for k = 1:numel(names)
            v = ps.(names{k});
            if isempty(v), continue; end
            if any(strcmp(names{k}, logicalOpts)), v = logical(v); end
            opts = [opts, {names{k}, v}]; %#ok<AGROW>
        end
        movieInfo = repmat(struct('xCoord', zeros(0, 2), 'yCoord', zeros(0, 2), 'amp', zeros(0, 2)), nF, 1);
        for k = 1:nF
            p = pointSourceDetection(double(movie.getFrame(f1 + k - 1)), sigma, opts{:});
            if ~isempty(p) && isfield(p, 'x') && ~isempty(p.x)
                movieInfo(k).xCoord = [p.x(:), getStd(p, 'x_pstd')];
                movieInfo(k).yCoord = [p.y(:), getStd(p, 'y_pstd')];
                movieInfo(k).amp = [p.A(:), getStd(p, 'A_pstd')];
            end
        end
        pointSourceParams = ps; %#ok<NASGU>
        save(fullfile(outDir, 'detection.mat'), 'movieInfo', 'pointSourceParams');
    otherwise
        error('trackbatch:method', 'Unknown detection method "%s"', det.method);
end
nDet = sum(arrayfun(@(m) size(m.xCoord, 1), movieInfo));
fprintf('Detected %d features\n', nDet);

if isfield(params.export, 'detections_csv') && params.export.detections_csv
    writeDetections(fullfile(outDir, 'detections.csv'), movieInfo, f1 - 1);
end

% ---- tracking -----------------------------------------------------------
trk = params.tracking;
gapCloseParam = trk.gapCloseParam;
costMatrices = normaliseCostMatrices(trk.costMatrices, gapCloseParam.timeWindow);
kalmanFunctions = trk.kalmanFunctions;
probDim = trk.probDim;
saveRes = struct('dir', outDir, 'filename', 'tracking.mat');
tracksFinal = trackCloseGapsKalmanSparse(movieInfo, costMatrices, gapCloseParam, ...
    kalmanFunctions, probDim, saveRes, 0);

if isfield(params.export, 'tracks_csv') && params.export.tracks_csv
    writeTracks(outDir, tracksFinal, f1 - 1);
end

stats = struct('n_frames', nF, 'n_detections', nDet, 'n_tracks', numel(tracksFinal), ...
    'seconds', round(toc(t0) * 10) / 10);
end

% -------------------------------------------------------------------------
function s = getStd(p, name)
if isfield(p, name), s = p.(name)(:); else, s = zeros(numel(p.x), 1); end
end

function cm = normaliseCostMatrices(cm, timeWindow)
% jsondecode gives a cell array when the structs differ; u-track wants a struct array.
if iscell(cm)
    tmp = struct('funcName', {}, 'parameters', {});
    for j = 1:numel(cm)
        tmp(j).funcName = cm{j}.funcName;
        tmp(j).parameters = cm{j}.parameters;
    end
    cm = tmp;
end
% The gap-closing cost function expects per-gap-length column vectors.
for j = 2:numel(cm)
    for f = {'brownStdMult', 'linStdMult'}
        if isfield(cm(j).parameters, f{1}) && isscalar(cm(j).parameters.(f{1}))
            cm(j).parameters.(f{1}) = cm(j).parameters.(f{1}) * ones(timeWindow, 1);
        end
    end
end
end

function movie = openMovie(path, channel)
[~, ~, ext] = fileparts(path);
if any(strcmpi(ext, {'.tif', '.tiff'}))
    info = imfinfo(path);
    nPages = numel(info);
    nC = 1; nZ = 1; nT = nPages;
    d = '';
    if isfield(info, 'ImageDescription'), d = info(1).ImageDescription; end
    if isempty(d) && isfield(info, 'Comment'), d = info(1).Comment; end  % Octave
    if ischar(d) && ~isempty(d)
        nC = tagValue(d, 'channels', 1);
        nZ = tagValue(d, 'slices', 1);
        nT = tagValue(d, 'frames', nPages / max(1, nC * nZ));
    end
    if nZ > 1 && nT == 1
        nT = nZ; nZ = 1;  % time stored as Z - the usual ImageJ mix-up
    elseif nZ > 1
        error('trackbatch:3d', 'u-track batch supports 2D movies only (%d z-slices found).', nZ);
    end
    if channel > nC, error('trackbatch:channel', 'Channel %d requested but image has %d.', channel, nC); end
    movie.nFrames = nT;
    movie.getFrame = @(t) imread(path, (t - 1) * nC + channel, 'Info', info);
else
    if ~exist('bfGetReader', 'file')
        error('trackbatch:bioformats', 'Bio-Formats (bfGetReader) is needed to read %s files.', ext);
    end
    r = bfGetReader(path);
    if r.getSizeZ() > 1 && r.getSizeT() > 1
        error('trackbatch:3d', 'u-track batch supports 2D movies only.');
    end
    movie.nFrames = max(r.getSizeT(), r.getSizeZ());
    useZ = r.getSizeT() == 1 && r.getSizeZ() > 1;
    if useZ
        movie.getFrame = @(t) bfGetPlane(r, r.getIndex(t - 1, channel - 1, 0) + 1);
    else
        movie.getFrame = @(t) bfGetPlane(r, r.getIndex(0, channel - 1, t - 1) + 1);
    end
end
end

function v = tagValue(desc, key, default)
tok = regexp(desc, [key '=(\d+)'], 'tokens', 'once');
if isempty(tok), v = default; else, v = str2double(tok{1}); end
end

function writeDetections(path, movieInfo, offset)
fid = fopen(path, 'w');
c = onCleanup(@() fclose(fid));
fprintf(fid, 'FRAME,X,Y,AMP,X_STD,Y_STD,AMP_STD\n');
for k = 1:numel(movieInfo)
    m = movieInfo(k);
    for n = 1:size(m.xCoord, 1)
        fprintf(fid, '%d,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n', k + offset, m.xCoord(n, 1), m.yCoord(n, 1), ...
            m.amp(n, 1), m.xCoord(n, 2), m.yCoord(n, 2), m.amp(n, 2));
    end
end
end

function writeTracks(outDir, tracksFinal, offset)
fid = fopen(fullfile(outDir, 'tracks.csv'), 'w');
c1 = onCleanup(@() fclose(fid));
fprintf(fid, 'TRACK_ID,SEGMENT,FRAME,X,Y,AMP,X_STD,Y_STD,AMP_STD\n');
fev = fopen(fullfile(outDir, 'track_events.csv'), 'w');
c2 = onCleanup(@() fclose(fev));
fprintf(fev, 'TRACK_ID,FRAME,EVENT,SEGMENT,PARTNER_SEGMENT\n');
for it = 1:numel(tracksFinal)
    tr = tracksFinal(it);
    seq = tr.seqOfEvents;
    startF = min(seq(:, 1));
    M = tr.tracksCoordAmpCG;
    nCol = size(M, 2) / 8;
    for s = 1:size(M, 1)
        for k = 1:nCol
            v = M(s, (k - 1) * 8 + (1:8));  % [x y z amp dx dy dz damp]
            if ~isnan(v(1))
                fprintf(fid, '%d,%d,%d,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n', it, s, startF + k - 1 + offset, ...
                    v(1), v(2), v(4), v(5), v(6), v(8));
            end
        end
    end
    for e = 1:size(seq, 1)
        if seq(e, 2) == 1, ev = 'start'; else, ev = 'end'; end
        fprintf(fev, '%d,%d,%s,%d,%s\n', it, seq(e, 1) + offset, ev, seq(e, 3), num2str(seq(e, 4)));
    end
end
end

function writeText(path, txt)
fid = fopen(path, 'w', 'n', 'UTF-8');
fprintf(fid, '%s', txt);
fclose(fid);
end
